Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = "C:\Users\13527\Desktop\ESO\ESO"
$OutDir = Join-Path $Root "ACTIVE_CHAT_DROPS\CURRENT_PROGRESS_LOCKS"
$OutFile = Join-Path $OutDir "ESO_CURRENT_PROGRESS_LOCK_20260613.md"

Write-Host "=== SAVE ESO CURRENT PROGRESS LOCK ===" -ForegroundColor Cyan

if (!(Test-Path -LiteralPath $Root)) {
  throw "Missing repo root: $Root"
}

New-Item -ItemType Directory -Force -Path $OutDir | Out-Null

$Payload = ""
$Bytes = [Convert]::FromBase64String($Payload)
[System.IO.File]::WriteAllBytes($OutFile, $Bytes)

$Readback = Get-Content -LiteralPath $OutFile -Raw
if ($Readback -notmatch "LOCKED_CURRENT_PROGRESS / FAILURE_CHAIN_FROZEN / SNAP_FIT_PRESERVED") {
  throw "READBACK_FAILED: status line missing."
}
if ($Readback -notmatch "Remove the baked top ENTER THE INDEX button from the original PNG") {
  throw "READBACK_FAILED: current target missing."
}
if ($Readback -notmatch "Repeated Correction Gate") {
  throw "READBACK_FAILED: repeated correction gate missing."
}
if ($Readback -notmatch "Surface Classification Gate") {
  throw "READBACK_FAILED: surface classification gate missing."
}

$Hash = Get-FileHash -Algorithm SHA256 -LiteralPath $OutFile

Write-Host "DONE: current progress lock saved." -ForegroundColor Green
Write-Host "FILE: $OutFile" -ForegroundColor Cyan
Write-Host "SHA256: $($Hash.Hash)" -ForegroundColor Cyan
Write-Host ""
Write-Host "=== READBACK TOP ===" -ForegroundColor Cyan
Get-Content -LiteralPath $OutFile -TotalCount 80 | ForEach-Object { Write-Host $_ }
Write-Host ""
Write-Host "No page/css/image edit. No commit. No push." -ForegroundColor Green
